import sys

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        A = []
        for _ in range(N):
            A.append(int(next(iterator)))
    except StopIteration:
        return

    # We will try removing each element one by one and compute the GCD of the remaining N-1 elements.
    # The answer is the maximum of these values.
    # Since we can replace the removed element with a multiple of the GCD of the rest,
    # the final GCD will be exactly the GCD of the remaining N-1 elements.

    # Precompute prefix and suffix GCD arrays to answer queries in O(1).
    # prefix[i] = GCD(A[0], A[1], ..., A[i])
    # suffix[i] = GCD(A[i], A[i+1], ..., A[N-1])

    prefix = [0] * N
    suffix = [0] * N

    prefix[0] = A[0]
    for i in range(1, N):
        prefix[i] = gcd(prefix[i-1], A[i])

    suffix[N-1] = A[N-1]
    for i in range(N-2, -1, -1):
        suffix[i] = gcd(suffix[i+1], A[i])

    max_gcd = 0

    # Try removing index i (0-based)
    for i in range(N):
        if i == 0:
            # Remaining: A[1]...A[N-1] -> suffix[1]
            current_gcd = suffix[1] if N > 1 else 0
        elif i == N-1:
            # Remaining: A[0]...A[N-2] -> prefix[N-2]
            current_gcd = prefix[N-2]
        else:
            # Remaining: A[0]...A[i-1] and A[i+1]...A[N-1]
            current_gcd = gcd(prefix[i-1], suffix[i+1])

        if current_gcd > max_gcd:
            max_gcd = current_gcd

    print(max_gcd)

if __name__ == "__main__":
    solve()

